<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catalogue · {{ $organization->name }} · PharmaCare</title>
<style>:root{--o:#f47a20;--od:#bd4e08;--ink:#34251d;--muted:#755f53;--line:#eadbd1;--soft:#fff7f0;--danger:#b42318;--green:#18733d}*{box-sizing:border-box}body{margin:0;background:var(--soft);color:var(--ink);font-family:Inter,system-ui,sans-serif}header{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:13px 5%;background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:5}.brand{display:flex;align-items:center;gap:11px;color:var(--ink);font-weight:850;text-decoration:none}.brand img{width:46px;height:46px;object-fit:contain}nav{display:flex;gap:16px;flex-wrap:wrap}nav a{color:var(--od);font-weight:750;text-decoration:none}main{max-width:1380px;margin:28px auto;padding:0 20px}.head,.actions{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.muted{color:var(--muted)}.card,details.section{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px;margin-bottom:20px;box-shadow:0 12px 34px #7a35000e}details.section>summary{cursor:pointer;font-size:20px;font-weight:850}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.two{grid-template-columns:repeat(2,minmax(0,1fr))}label{display:block;font-weight:720;font-size:14px;margin:9px 0 5px}input,select,textarea{width:100%;padding:10px 11px;border:1px solid #d8c6bb;border-radius:9px;font:inherit;background:#fff}select[multiple]{min-height:105px}textarea{min-height:70px}.check{display:flex;gap:7px;align-items:center}.check input{width:auto}button,.button{border:0;border-radius:9px;padding:10px 13px;background:var(--o);color:#fff;font-weight:800;text-decoration:none;cursor:pointer}.danger{background:var(--danger)}.success{background:var(--green)}.secondary{background:#fff0e6;color:var(--od)}.message{padding:13px;border-radius:10px;background:#e9f8ee;color:var(--green)}.error{background:#fff0ee;color:var(--danger)}.item{border-top:1px solid #eee;padding:15px 0}.item:first-child{border-top:0}.ref-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.ref-box{border:1px solid var(--line);border-radius:13px;padding:14px}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef7f1;color:var(--green);font-size:12px;font-weight:800}.archive{border-left:4px solid #8c7569;padding-left:12px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:850px}th,td{text-align:left;padding:11px;border-bottom:1px solid #eee;font-size:14px}.expiry{color:#b42318;font-weight:800}@media(max-width:950px){.grid,.ref-grid{grid-template-columns:1fr 1fr}}@media(max-width:680px){header{position:static;align-items:flex-start;flex-direction:column}.grid,.two,.ref-grid{grid-template-columns:1fr}.head{align-items:flex-start}}</style></head>
